(()=>{const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches,desktop=matchMedia('(hover:hover) and (pointer:fine)').matches;const css=document.createElement('style');css.textContent=`@keyframes introPulse{50%{text-shadow:0 0 18px #fff,0 0 46px #00d9ff,0 0 64px #ff8a00;transform:scale(1.03)}}@keyframes introOut{to{opacity:0;visibility:hidden}}@keyframes sparkOut{to{opacity:0;transform:translate(-50%,-50%) scale(1.8) rotate(40deg)}}.site-intro{position:fixed;inset:0;z-index:20000;display:grid;place-items:center;text-align:center;padding:24px;background:radial-gradient(circle,#1594ff,#0060c7 58%,#003d82)}.site-intro.hide{animation:introOut .55s forwards}.site-intro b{font-size:clamp(34px,7vw,82px);line-height:1;color:#fff;text-transform:uppercase;letter-spacing:-2px;animation:introPulse .7s ease-in-out infinite alternate;max-width:95vw}.site-intro b span{color:#ff9d00}.trail{position:fixed;z-index:19999;pointer-events:none;width:20px;height:20px;display:grid;place-items:center;font-size:16px;filter:drop-shadow(0 0 5px #fff) drop-shadow(0 0 9px #00d9ff) drop-shadow(0 0 10px #ff8a00);transform:translate(-50%,-50%);animation:sparkOut .65s forwards}.lab-glass{position:relative!important;background:linear-gradient(135deg,rgba(255,255,255,.62),rgba(220,244,255,.28))!important;border:1px solid rgba(255,255,255,.88)!important;box-shadow:0 18px 48px rgba(0,72,145,.16),inset 0 1px 0 rgba(255,255,255,.95)!important;backdrop-filter:blur(14px) saturate(135%)!important;-webkit-backdrop-filter:blur(14px) saturate(135%)!important;overflow:hidden}.lab-glass-dark{background:linear-gradient(135deg,rgba(4,65,132,.52),rgba(0,140,255,.22))!important;border:1px solid rgba(255,255,255,.55)!important}.bottom-bible-verse{max-width:900px;margin:42px auto 0;padding:0 20px;text-align:center}.bottom-bible-verse .hero-verse{position:static!important;display:block!important;max-width:900px!important;margin:0 auto!important;padding:22px 28px!important;text-align:center!important;color:#0752ad!important;font-size:clamp(18px,2.4vw,25px)!important;font-weight:900!important;line-height:1.5!important;text-shadow:none!important;border:1px solid rgba(255,255,255,.9)!important;border-radius:20px!important;background:linear-gradient(135deg,rgba(255,255,255,.72),rgba(220,244,255,.38))!important;box-shadow:0 18px 48px rgba(0,72,145,.16)!important}.microscope-instruction-wrap{position:relative;z-index:6;margin:0 auto 24px;width:max-content;max-width:calc(100% - 32px)}.microscope-instruction{padding:10px 18px;border:2px solid #ffffffb8;border-radius:999px;background:#063b78a8;color:#fff;text-align:center;font-size:14px;font-weight:900;box-shadow:0 0 18px #00d9ff66;white-space:normal}.microscope-lens{position:fixed;z-index:10000;width:min(620px,94vw);height:min(620px,94vw);border-radius:50%;pointer-events:none;opacity:0;overflow:hidden;transform:translate(-50%,-50%) scale(.65);transition:opacity .16s ease,transform .16s ease;background:radial-gradient(circle at 38% 34%,#ffffff20 0 7%,transparent 22%),radial-gradient(circle,transparent 62%,#001b3a88 80%,#001020e8 100%);border:8px solid #fff;box-shadow:0 0 0 8px #008cff,0 0 32px #00d9ff99}.microscope-lens.active{opacity:1;transform:translate(-50%,-50%) scale(1)}.microscope-view{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;padding:82px 68px;color:#fff;overflow:hidden}.microscope-copy{width:100%;max-height:100%;line-height:1.28;font-weight:700;text-shadow:0 2px 4px #001b3a;white-space:pre-wrap;overflow-wrap:anywhere;overflow:hidden}.cross-v,.cross-h{position:absolute;background:#ffffff4d}.cross-v{width:1px;height:100%;left:50%}.cross-h{height:1px;width:100%;top:50%}.microscope-label{position:absolute;left:50%;bottom:5%;transform:translateX(-50%);padding:5px 10px;border-radius:999px;background:#001f45df;color:#fff;font-size:11px;font-weight:900;letter-spacing:1px}.scope-prompt{position:fixed;z-index:10004;left:50%;top:90px;transform:translateX(-50%);display:none;max-width:calc(100vw - 28px);padding:12px 18px;border:2px solid #fff;border-radius:999px;background:#0752addf;color:#fff;font-weight:900;text-align:center}.scope-prompt.show{display:block}.scope-setup{position:fixed;z-index:10005;inset:0;display:none;align-items:center;justify-content:center;padding:20px;background:rgba(0,24,58,.58)}.scope-setup.show{display:flex}.scope-card{width:min(520px,92vw);padding:30px;border-radius:26px;text-align:center;color:#fff;background:linear-gradient(135deg,rgba(5,69,140,.96),rgba(0,140,255,.9));border:2px solid #ffffffcc;box-shadow:0 20px 55px #001a3c88}.scope-card h3{font-size:28px;margin:0 0 8px}.scope-card p{font-size:14px;color:#eaf7ff}.mag-options{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-top:18px}.mag-btn{border:2px solid #ffffffaa;border-radius:14px;padding:12px 5px;background:#ffffff16;color:#fff;font-weight:900;font-size:16px;cursor:pointer}.mag-btn:hover{background:#ff8a00}.scope-cancel{margin-top:14px;border:0;background:transparent;color:#fff;text-decoration:underline;font-weight:800;cursor:pointer}.scope-selecting *{-webkit-user-select:text!important;user-select:text!important}.scope-selecting ::selection{background:#ff9d00;color:#062b59}.microscope-active,.microscope-active *{-webkit-user-select:none!important;user-select:none!important}.microscope-active ::selection{background:transparent!important}@media(max-width:760px){.site-intro b{font-size:clamp(32px,11vw,58px)}.microscope-instruction-wrap{display:none!important}.lab-glass{backdrop-filter:none!important;-webkit-backdrop-filter:none!important}.bottom-bible-verse{margin-top:28px;padding:0 8px}.bottom-bible-verse .hero-verse{padding:17px!important;font-size:16px!important}}@media(prefers-reduced-motion:reduce){.site-intro b,.trail{animation:none}.trail{display:none}}`;document.head.appendChild(css);
const intro=document.createElement('div');intro.className='site-intro';intro.innerHTML='<b>THE DEPTHS OF <span>IMMUNOTHERAPY</span></b>';document.body.prepend(intro);setTimeout(()=>intro.classList.add('hide'),reduced?250:1350);setTimeout(()=>intro.remove(),reduced?850:2000);let last=0,n=0;function spark(x,y){if(reduced)return;const e=document.createElement('i');e.className='trail';e.textContent=n++%3===0?'🧬':'✦';e.style.left=x+'px';e.style.top=y+'px';e.style.color=n%2?'#00d9ff':'#ff8a00';document.body.appendChild(e);setTimeout(()=>e.remove(),700)}addEventListener('pointermove',e=>{if(e.pointerType==='mouse'&&performance.now()-last>55){last=performance.now();spark(e.clientX,e.clientY)}});
document.querySelectorAll('.summary-card,.research-person,.info-card').forEach(e=>e.classList.add('lab-glass'));document.querySelectorAll('.molecule-link').forEach(e=>e.classList.add('lab-glass-dark'));const verse=document.querySelector('.hero-verse'),research=document.querySelector('.research-by'),grid=document.querySelector('.research-grid');if(verse&&research&&!verse.closest('.bottom-bible-verse')){const w=document.createElement('div');w.className='bottom-bible-verse';w.appendChild(verse);if(grid&&grid.parentNode)grid.parentNode.insertBefore(w,grid.nextSibling);else research.appendChild(w)}
if(!desktop)return;const hero=document.querySelector('.hero');if(hero){const wrap=document.createElement('div');wrap.className='microscope-instruction-wrap';wrap.innerHTML='<div class="microscope-instruction lab-glass-dark">Computer only: Double-click to enter and leave microscope mode! Highlight text to magnify.</div>';hero.insertBefore(wrap,hero.firstChild)}const lens=document.createElement('div');lens.className='microscope-lens';lens.innerHTML='<div class="microscope-view"><div class="microscope-copy"></div></div><i class="cross-v"></i><i class="cross-h"></i><span class="microscope-label">MICROSCOPE MODE</span>';document.body.appendChild(lens);const copy=lens.querySelector('.microscope-copy'),view=lens.querySelector('.microscope-view');const prompt=document.createElement('div');prompt.className='scope-prompt';prompt.textContent='Highlight the exact text you want to magnify.';document.body.appendChild(prompt);const setup=document.createElement('div');setup.className='scope-setup';setup.innerHTML='<div class="scope-card"><h3>Select Magnification</h3><p>Choose your preferred lens. Longer selections may require smaller text to fit.</p><div class="mag-options"><button class="mag-btn" data-mag="1.25">1.25×</button><button class="mag-btn" data-mag="1.5">1.5×</button><button class="mag-btn" data-mag="2">2×</button><button class="mag-btn" data-mag="3">3×</button></div><button class="scope-cancel">Cancel</button></div>';document.body.appendChild(setup);let active=false,selecting=false,selected='',mag=1.25,x=innerWidth/2,y=innerHeight/2;function clearSel(){const s=getSelection();if(s)s.removeAllRanges()}function fits(){return copy.scrollHeight<=view.clientHeight-4&&copy.scrollWidth<=view.clientWidth-4}function fit(){let hi=Math.min(38,22*mag),lo=.5;copy.style.fontSize=hi+'px';if(fits())return;for(let i=0;i<18;i++){const mid=(lo+hi)/2;copy.style.fontSize=mid+'px';if(fits())lo=mid;else hi=mid}copy.style.fontSize=Math.max(.5,lo-.08)+'px'}function place(){const half=Math.min(310,innerWidth*.47);x=Math.max(half+10,Math.min(innerWidth-half-10,x));y=Math.max(half+10,Math.min(innerHeight-half-10,y));lens.style.left=x+'px';lens.style.top=y+'px'}function exit(){active=false;selecting=false;lens.classList.remove('active');prompt.classList.remove('show');setup.classList.remove('show');document.body.classList.remove('microscope-active','scope-selecting');copy.textContent='';selected='';clearSel()}function start(e){if(e.target.closest('a,button,.scope-setup'))return;x=e.clientX;y=e.clientY;clearSel();selecting=true;document.body.classList.add('scope-selecting');prompt.classList.add('show')}document.addEventListener('dblclick',e=>{e.preventDefault();if(active){exit();return}if(setup.classList.contains('show'))return;start(e)});document.addEventListener('mouseup',()=>{if(!selecting)return;setTimeout(()=>{const t=getSelection()?.toString().trim()||'';if(!t)return;selected=t;selecting=false;prompt.classList.remove('show');document.body.classList.remove('scope-selecting');setup.classList.add('show')},0)});setup.querySelectorAll('.mag-btn').forEach(b=>b.addEventListener('click',()=>{mag=parseFloat(b.dataset.mag);active=true;setup.classList.remove('show');document.body.classList.add('microscope-active');copy.textContent=selected;place();lens.classList.add('active');fit();clearSel()}));setup.querySelector('.scope-cancel').addEventListener('click',exit);addEventListener('pointermove',e=>{if(active&&e.pointerType==='mouse'){x=e.clientX;y=e.clientY;place()}},{passive:true});document.addEventListener('copy',e=>{if(active)e.preventDefault()});document.addEventListener('cut',e=>{if(active)e.preventDefault()});addEventListener('resize',()=>{if(active){place();fit()}},{passive:true})})();